import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer
import kotlin.math.floorMod

data class Matrix(val a: LongArray) {
    // 3x3 matrix stored row-major
    fun mul(other: Matrix, mod: Long): Matrix {
        val res = LongArray(9)
        for (i in 0 until 3) {
            for (k in 0 until 3) {
                val aik = a[i * 3 + k]
                if (aik == 0L) continue
                for (j in 0 until 3) {
                    val idx = i * 3 + j
                    res[idx] = (res[idx] + aik * other.a[k * 3 + j]) % mod
                }
            }
        }
        return Matrix(res)
    }

    fun apply(vec: LongArray, mod: Long): LongArray {
        val res = LongArray(3)
        for (i in 0 until 3) {
            var s = 0L
            for (j in 0 until 3) {
                s = (s + a[i * 3 + j] * vec[j]) % mod
            }
            res[i] = s
        }
        return res
    }

    companion object {
        fun identity(): Matrix {
            val a = LongArray(9)
            for (i in 0 until 3) a[i * 3 + i] = 1L
            return Matrix(a)
        }
    }
}

fun powMatrix(base: Matrix, exp: Long, mod: Long): Matrix {
    var e = exp
    var b = base
    var res = Matrix.identity()
    while (e > 0) {
        if ((e and 1L) != 0L) res = res.mul(b, mod)
        b = b.mul(b, mod)
        e = e shr 1
    }
    return res
}

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
