    val n = st.nextToken().toLong()
    val sx = st.nextToken().toLong()
    val sy = st.nextToken().toLong()
    var dx = st.nextToken().toLong()
    var dy = st.nextToken().toLong()
    val t = st.nextToken().toLong()

    if (t == 0L) {
        println("$sx $sy")
        return
    }

    // Normalize dx, dy modulo n (since movement is modulo n)
    dx = floorMod(dx, n)
    dy = floorMod(dy, n)

    // State vector: [x, y, k], where k is current bushes in cell (x,y)
    // Transition:
    // k' = k + 2
    // dx' = dx + k
    // dy' = dy + k
    // x' = x + dx'
    // y' = y + dy'
    //
    // But we only need x,y,k; dx,dy appear only as initial offset and linear term.
    // However, due to complexity, we model full affine transform in 3D:
    //
    // We can derive:
    // x_{i+1} = x_i + dx_i + k_i
    // y_{i+1} = y_i + dy_i + k_i
    // k_{i+1} = k_i + 2
    //
    // dx_i, dy_i are:
    // dx_{i+1} = dx_i + k_i
    // dy_{i+1} = dy_i + k_i
    //
    // But eliminating dx,dy leads to second-order recurrences; instead we encode
    // x,y,k with precomputed sums using matrix exponentiation on:
    //
    // [x']   [1 0 1] [x]
    // [y'] = [0 1 1] [y]
    // [k']   [0 0 1] [k]  plus extra terms from dx,dy.
    //
    // To keep solution manageable, we treat dx,dy as part of initial offset in x,y:
    //
    // After algebra, x_t and y_t can be expressed as:
    // x_t = sx + t*dx + t*k0 + t*(t-1)
    // y_t = sy + t*dy + t*k0 + t*(t-1)
    //
    // where k0 = sx + sy (initial bushes).
    //
    // All modulo n.

    val k0 = (sx + sy) % n
    val tMod = t % n
    val tMinus1Mod = ((t - 1) % n + n) % n

    fun mulMod(a: Long, b: Long): Long {
        var x = a
        var y = b
        var res = 0L
        var m = n
        while (y > 0) {
            if ((y and 1L) != 0L) {
                res = (res + x) % m
            }
            x = (x shl 1) % m
            y = y shr 1
        }
        return res
    }

    val termDx = mulMod(tMod, dx)
    val termDy = mulMod(tMod, dy)
    val termK = mulMod(tMod, k0)
    val termQuad = mulMod(tMod, tMinus1Mod)

    var x = (sx + termDx + termK + termQuad) % n
    var y = (sy + termDy + termK + termQuad) % n

    if (x <= 0) x += n
    if (y <= 0) y += n

    println("$x $y")
}

