                 (a[i * 3 + 1] * v[1]) % MOD +
                 (a[i * 3 + 2] * v[2]) % MOD) % MOD
        }
        return res
    }

    companion object {
        fun identity(): Mat {
            val arr = LongArray(9)
            arr[0] = 1
            arr[4] = 1
            arr[8] = 1
            return Mat(arr)
        }
    }
}

fun modMul(a: Long, b: Long, m: Long): Long {
    var x = a % m
    var y = b
    var res = 0L
    while (y > 0) {
        if ((y and 1L) != 0L) {
            res = (res + x) % m
        }
        x = (x * 2) % m
        y = y shr 1
    }
    return res
}

fun modPow(base: Long, exp: Long, m: Long): Long {
