fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val st = StringTokenizer(br.readLine())
    val n = st.nextToken().toLong()
    var x = st.nextToken().toLong()
    var y = st.nextToken().toLong()
    var dx = st.nextToken().toLong()
    var dy = st.nextToken().toLong()
    val t = st.nextToken().toLong()

    if (t == 0L) {
        println("$x $y")
        return
    }

    // Normalize initial dx, dy to [0, n-1] range for movement
    fun norm(v: Long): Long {
        val m = v % n
        return if (m < 0) m + n else m
    }

    dx = norm(dx)
    dy = norm(dy)

    // Precompute powers of 2 up to 60 (since t <= 1e18)
    val maxK = 60
    val stepDx = LongArray(maxK + 1)
    val stepDy = LongArray(maxK + 1)
    val stepX = LongArray(maxK + 1)
    val stepY = LongArray(maxK + 1)

    // For k = 0: one step
    // k0 = x + y (initial bushes)
    var k0 = x + y
    var curDx = (dx + k0) % n
    var curDy = (dy + k0) % n
    stepDx[0] = curDx
    stepDy[0] = curDy
    stepX[0] = ((x + curDx - 1) % n) + 1
    stepY[0] = ((y + curDy - 1) % n) + 1

    // Precompute for powers of two
    for (k in 1..maxK) {
        // From state after 2^(k-1) steps, apply same block again
        val prevDx = stepDx[k - 1]
        val prevDy = stepDy[k - 1]
        val prevX = stepX[k - 1]
        val prevY = stepY[k - 1]

        // Total bushes eaten in block of size 2^(k-1):
        // sum over i: (x_i + y_i) + i
        // But we only need resulting dx,dy and final position.
        // We'll simulate the second block using the precomputed block as a template.

        // For block doubling:
        // New dx,dy after 2^(k-1) more steps:
        // dx' = prevDx + stepDx[k-1]
        // dy' = prevDy + stepDy[k-1]
        stepDx[k] = (prevDx + stepDx[k - 1]) % n
        stepDy[k] = (prevDy + stepDy[k - 1]) % n

        // Position after applying block again:
        // From prevX, prevY with speed prevDx, prevDy, apply movement of block:
        val nx = ((prevX + stepDx[k - 1] - 1) % n) + 1
        val ny = ((prevY + stepDy[k - 1] - 1) % n) + 1
        stepX[k] = nx
        stepY[k] = ny
    }

    var remaining = t
    var curX = x
    var curY = y
    var curDX = dx
    var curDY = dy

    var first = true
    var bit = 0
    while (remaining > 0) {
        if ((remaining and 1L) == 1L) {
            if (first) {
                // For the first block, we must use the exact precomputed from initial state
                curDX = stepDx[bit]
                curDY = stepDy[bit]
                curX = stepX[bit]
                curY = stepY[bit]
                first = false
            } else {
                // Apply block starting from current state
                val addDx = stepDx[bit]
                val addDy = stepDy[bit]
                curDX = (curDX + addDx) % n
                curDY = (curDY + addDy) % n
                curX = ((curX + addDx - 1) % n) + 1
                curY = ((curY + addDy - 1) % n) + 1
            }
        }
        remaining = remaining shr 1
        bit++
    }

    println("$curX $curY")
}

