private fun modMul(a: Long, b: Long, mod: Long): Long {
    var x = a % mod
    var y = b % mod
    var res = 0L
    while (y > 0) {
        if ((y and 1L) != 0L) {
            res = (res + x) % mod
        }
        x = (x shl 1) % mod
        y = y shr 1
    }
    return res
}

private fun modAdd(a: Long, b: Long, mod: Long): Long {
    var res = a + b
    if (res >= mod) res -= mod
    return res
}

private fun modSub(a: Long, b: Long, mod: Long): Long {
    var res = a - b
    if (res < 0) res += mod
    return res
}

private fun modPow(base: Long, exp: Long, mod: Long): Long {
    var b = base % mod
    var e = exp
    var res = 1L
    while (e > 0) {
        if ((e and 1L) != 0L) {
            res = modMul(res, b, mod)
        }
        b = modMul(b, b, mod)
        e = e shr 1
    }
    return res
}

private fun modInv(a: Long, mod: Long): Long {
    // mod is prime (n up to 1e9, but we rely on problem constraints from CF: n is prime)
    return modPow(a, mod - 2, mod)
}

