    // dx_{k+1} = dx_k + k + 1 + x_k + y_k
    // Similar for y
    // Using known solution from editorial:
    // After t steps:
    // x_t = sx + dx * t + something * t^2 (mod n)
    // But deriving is complex; instead we simulate using matrix exponentiation in mod n
    // State: [x, y, dx, dy, k, 1]
    // However t up to 1e18, dimension 6 -> feasible with O(6^3 log t)

    val dim = 6
    fun mulMat(a: Array<LongArray>, b: Array<LongArray>): Array<LongArray> {
        val res = Array(dim) { LongArray(dim) }
        for (i in 0 until dim) {
            for (k in 0 until dim) {
                if (a[i][k] == 0L) continue
                val aik = a[i][k]
                for (j in 0 until dim) {
                    if (b[k][j] == 0L) continue
                    res[i][j] = (res[i][j] + modMul(aik, b[k][j], n)) % n
                }
            }
        }
        return res
    }

    fun matPow(mat: Array<LongArray>, exp: Long): Array<LongArray> {
        var e = exp
        var base = mat
        val res = Array(dim) { LongArray(dim) }
        for (i in 0 until dim) res[i][i] = 1L % n
        while (e > 0) {
            if ((e and 1L) != 0L) {
                res.indices.forEach { i ->
                    val tmp = LongArray(dim)
                    for (k in 0 until dim) {
                        if (res[i][k] == 0L) continue
                        val rik = res[i][k]
                        for (j in 0 until dim) {
                            if (base[k][j] == 0L) continue
                            tmp[j] = (tmp[j] + modMul(rik, base[k][j], n)) % n
                        }
                    }
                    for (j in 0 until dim) res[i][j] = tmp[j]
                }
