    // k is step index (starting from 0), but we need k+1 each step.
    // However, number of bushes eaten = x + y + (k+1) (since each cell gets +1 per second).
    // This is consistent with problem statement.
    val m = Array(dim) { LongArray(dim) }

    // x' = x + dx
    m[0][0] = 1L % n
    m[0][2] = 1L % n

    // y' = y + dy
    m[1][1] = 1L % n
    m[1][3] = 1L % n

    // dx' = dx + (x + y + k + 1)
    m[2][2] = 1L % n // dx
    m[2][0] = (m[2][0] + 1L) % n // x
    m[2][1] = (m[2][1] + 1L) % n // y
    m[2][4] = (m[2][4] + 1L) % n // k
    m[2][5] = (m[2][5] + 1L) % n // constant 1

    // dy' = dy + (x + y + k + 1)
    m[3][3] = 1L % n
    m[3][0] = (m[3][0] + 1L) % n
    m[3][1] = (m[3][1] + 1L) % n
    m[3][4] = (m[3][4] + 1L) % n
    m[3][5] = (m[3][5] + 1L) % n

    // k' = k + 1
    m[4][4] = 1L % n
    m[4][5] = (m[4][5] + 1L) % n

    // constant 1 stays 1
    m[5][5] = 1L % n

    val mp = matPow(m, t)

    val state = LongArray(dim)
    state[0] = (sx - 1 + n) % n
    state[1] = (sy - 1 + n) % n
    state[2] = dx % n
    state[3] = dy % n
    state[4] = 0L
    state[5] = 1L % n

    val resState = LongArray(dim)
    for (i in 0 until dim) {
        var v = 0L
        for (j in 0 until dim) {
            if (mp[i][j] == 0L) continue
            v = (v + modMul(mp[i][j], state[j], n)) % n
        }
        resState[i] = v
    }

    val finalX = (resState[0] + 1 + n) % n
    val finalY = (resState[1] + 1 + n) % n
    val fx = if (finalX == 0L) n else finalX
    val fy = if (finalY == 0L) n else finalY
    println("$fx $fy")
}

