                if (aik == 0L) continue
                val k3 = k * 3
                for (j in 0 until 3) {
                    r[i3 + j] = (r[i3 + j] + aik * other.a[k3 + j]) % mod
                }
            }
        }
        return Mat(r)
    }

    fun apply(vec: LongArray, mod: Long): LongArray {
        val res = LongArray(3)
        for (i in 0 until 3) {
            var sum = 0L
            for (j in 0 until 3) {
                sum = (sum + a[i * 3 + j] * vec[j]) % mod
            }
            res[i] = sum
        }
        return res
    }

    companion object {
        fun identity(): Mat {
            val a = LongArray(9)
            for (i in 0 until 3) a[i * 3 + i] = 1L
            return Mat(a)
        }
    }
}

