import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer

private const val MOD = 1000000007L

fun modAdd(a: Long, b: Long, m: Long): Long {
    var res = a + b
    if (res >= m) res -= m
    return res
}

fun modMul(a: Long, b: Long, m: Long): Long {
    var x = a % m
    var y = b % m
    var res = 0L
    while (y > 0) {
        if ((y and 1L) != 0L) {
            res += x
            if (res >= m) res -= m
        }
        x = (x shl 1) % m
        y = y shr 1
    }
    return res
}

fun matMul(a: Array<LongArray>, b: Array<LongArray>, m: Long): Array<LongArray> {
    val res = Array(4) { LongArray(4) }
    for (i in 0 until 4) {
        for (k in 0 until 4) {
            if (a[i][k] == 0L) continue
            val aik = a[i][k]
            for (j in 0 until 4) {
                if (b[k][j] == 0L) continue
                val add = modMul(aik, b[k][j], m)
                res[i][j] = modAdd(res[i][j], add, m)
            }
        }
    }
    return res
}

fun matPow(mat: Array<LongArray>, exp: Long, m: Long): Array<LongArray> {
    var e = exp
    var base = mat
    val res = Array(4) { LongArray(4) }
    for (i in 0 until 4) res[i][i] = 1L
    while (e > 0) {
        if ((e and 1L) != 0L) {
            res.indices.forEach { i ->
                res[i] = res[i]
            }
            val tmp = matMul(res, base, m)
            for (i in 0 until 4) {
                for (j in 0 until 4) res[i][j] = tmp[i][j]
            }
        }
        val tmpBase = matMul(base, base, m)
        for (i in 0 until 4) {
            for (j in 0 until 4) base[i][j] = tmpBase[i][j]
        }
        e = e shr 1
    }
    return res
}

