    val At = matPow(A, t, MOD)

    fun computeSumDx(): Long {
        val v0 = longArrayOf(dx0m, 0L, 0L, 1L)
        var res = 0L
        for (j in 0 until 4) {
            val add = modMul(At[0][j], v0[j], MOD)
            res = modAdd(res, add, MOD)
        }
