import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer
import kotlin.math.floorMod

private const val MOD: Long = 1_000_000_007L

data class Mat(val a: LongArray) {
    // 3x3 matrix stored row-major
    operator fun times(other: Mat): Mat {
        val res = LongArray(9)
        for (i in 0 until 3) {
            val i0 = i * 3
            for (k in 0 until 3) {
                val v = a[i0 + k]
                if (v == 0L) continue
                val k0 = k * 3
                res[i0] = (res[i0] + v * other.a[k0]) % MOD
                res[i0 + 1] = (res[i0 + 1] + v * other.a[k0 + 1]) % MOD
                res[i0 + 2] = (res[i0 + 2] + v * other.a[k0 + 2]) % MOD
            }
        }
        return Mat(res)
    }
}

fun matPow(base: Mat, exp: Long): Mat {
    var e = exp
    var b = base
    // identity
    var res = Mat(longArrayOf(
        1,0,0,
        0,1,0,
        0,0,1
    ))
    while (e > 0) {
        if ((e and 1L) != 0L) res = res * b
        b = b * b
        e = e shr 1
    }
    return res
}

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val st = StringTokenizer(br.readLine())
    val n = st.nextToken().toLong()
    val sx = st.nextToken().toLong()
    val sy = st.nextToken().toLong()
    var dx = st.nextToken().toLong()
    var dy = st.nextToken().toLong()
    val t = st.nextToken().toLong()

    if (t == 0L) {
        println("$sx $sy")
        return
    }

    // Normalize dx, dy into [0, n-1] for modular movement
    dx = floorMod(dx, n)
    dy = floorMod(dy, n)

    // Matrix for dx: [dx_{k+1}]   [1 1 0] [dx_k]
    //                [k+1      ] = [0 1 1] [k  ]
    //                [1        ]   [0 0 1] [1  ]
    val mDx = Mat(longArrayOf(
        1,1,0,
        0,1,1,
        0,0,1
    ))
    val mDy = mDx // same structure

    val powDx = matPow(mDx, t)
    val powDy = powDx

    // initial vector for dx: [dx0, 0, 1]
    val dxFinal = (
        powDx.a[0] * dx % MOD +
        powDx.a[1] * 0L % MOD +
        powDx.a[2] * 1L % MOD
    ) % MOD

    val dyFinal = (
        powDy.a[0] * dy % MOD +
        powDy.a[1] * 0L % MOD +
        powDy.a[2] * 1L % MOD
    ) % MOD

    // total displacement is sum of dx_k, dy_k over k=0..t-1
    // sum dx_k = dx0 * S1 + S2, where:
    // S1 = sum_{k=0}^{t-1} C(k+1,1) = t(t+1)/2
    // S2 = sum_{k=0}^{t-1} C(k+1,2) = t(t+1)(t-1)/6
    // but easier: we already have dx_t and recurrence:
    // dx_{k+1} - dx_k = k+1 => dx_t = dx0 + t(t+1)/2
    // sum dx_k = t*dx0 + t(t+1)(t+2)/6
    val tMod = t % MOD
    val t1 = (tMod * ((tMod + 1) % MOD)) % MOD
    val t2 = (t1 * ((tMod + 2) % MOD)) % MOD
    val inv6 = 166666668L // modular inverse of 6 mod 1e9+7

    val sumCoeff = t2 * inv6 % MOD
    val sumDx = (tMod * dx % MOD + sumCoeff) % MOD
    val sumDy = (tMod * dy % MOD + sumCoeff) % MOD

    // final position
    val finalX = ((sx - 1 + sumDx % n + n) % n) + 1
    val finalY = ((sy - 1 + sumDy % n + n) % n) + 1

    println("$finalX $finalY")
}
